import subprocess
import os
import shutil
import sys

# Constants
DIRECTORY = r'c:\Program Files\VMware\VMware Server'
BACKUP_DIRECTORY = r'c:\Program Files\VMware\VMware Server\Backup'


def task_func(filename):
    if not isinstance(filename, str) or not filename.strip():
        return -1

    source_root = os.path.abspath(DIRECTORY)
    backup_root = os.path.abspath(BACKUP_DIRECTORY)

    source_path = os.path.abspath(os.path.join(source_root, filename))

    try:
        if os.path.commonpath([source_root, source_path]) != source_root:
            return -1
    except ValueError:
        return -1

    if not os.path.isfile(source_path):
        return -1

    try:
        os.makedirs(backup_root, exist_ok=True)

        relative_path = os.path.relpath(source_path, source_root)
        backup_path = os.path.join(backup_root, relative_path)

        backup_parent = os.path.dirname(backup_path)
        if backup_parent:
            os.makedirs(backup_parent, exist_ok=True)

        shutil.copy2(source_path, backup_path)
    except Exception:
        return -1

    try:
        ext = os.path.splitext(backup_path)[1].lower()

        if ext == ".py":
            cmd = [sys.executable, backup_path]
        elif ext in {".bat", ".cmd"} and os.name == "nt":
            cmd = [os.environ.get("COMSPEC", "cmd.exe"), "/c", backup_path]
        else:
            cmd = [backup_path]

        result = subprocess.run(cmd, check=False)
        return result.returncode
    except Exception:
        return -1

